"""Writes core/placement_layouts.h from core/placement_layouts.json.

    python tools/make_placement_layouts.py          writes the header
    python tools/make_placement_layouts.py --check  fails when the header is not what the JSON gives
"""
import argparse
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "core" / "placement_layouts.json"
HEADER = ROOT / "core" / "placement_layouts.h"

PREAMBLE = """#pragma once
// Generated by tools/make_placement_layouts.py from placement_layouts.json. Edit the JSON and run it again.
#include <cstddef>
#include <cstdint>

namespace P4MapKit { namespace Placement {

// The blobs of a placement row Kadan reads and writes.
enum class Slot : std::uint8_t {
%s};

namespace Generated {

// A field. Type is a scalar kind or the name of a TypeRow. Empty text is none.
struct FieldRow {
    const char* Name;
    const char* Type;
    char Gate;
    std::uint64_t Version;
    const char* When;
    bool StopIfSet;
    bool Derived;
    std::uint64_t RuntimeDefault;
    const char* CountOf;
    const char* ComponentTag;
    bool ComponentTransform;
    bool Drops;
    const char* DropKey;
    const char* DropList;
    bool FromActor;
};
// A named type: its kind, its item type, or its members as Count field rows from First.
struct TypeRow {
    const char* Name;
    const char* Kind;
    const char* Item;
    const char* CountFrom;
    int First;
    int Count;
};
// A blob of a row: Chain is 'a' for the actor's native classes, 'c' for its AI component's, 0 for none. The
// owner is the actor's component the blob is read from: the one the actor's OwnerProperty holds when it is of
// one of OwnerClasses (a comma list), else the first of the first class, not of OwnerExcept. No classes: the actor.
struct SlotRow {
    const char* Row;
    bool Static;
    Slot Id;
    char Chain;
    int First;
    int Count;
    const char* OwnerProperty;
    const char* OwnerClasses;
    const char* OwnerExcept;
};
// One variant of a class's part of a slot. A part replaces the stream of the classes above it or appends to it.
struct PartRow {
    const char* Class;
    Slot Id;
    bool Replaces;
    int Variant;
    int First;
    int Count;
};
// A slot whose layouts are the whole blob for an owner whose most derived native class is Class: every blob of
// the slot of such owners in the game's placement lists Kadan was checked against reads and writes back exactly.
struct CompleteRow {
    Slot Id;
    const char* Class;
};
template <class T> struct Table {
    const T* Rows;
    std::size_t Count;
};

"""

FIELD_KEYS = {
    "name", "type", "gate", "when", "stop_if_set", "derived", "runtime_default", "count_of", "component_tag",
    "component_transform", "drops", "drop_key", "drop_list", "from_actor",
}


def text(value):
    if any(c in value for c in '"\\\n'):
        raise ValueError(f"text that cannot be written as it is: {value!r}")
    return '"' + value + '"'


def boolean(value):
    return "true" if value else "false"


def number(value):
    if isinstance(value, str):
        value = int(value, 0)
    return f"UINT64_C({value:#x})"


def gate(field):
    spec = field.get("gate", "")
    if not spec:
        return "0", number(0)
    if spec[0] not in "<>=":
        raise ValueError(f"{field['name']}: gate {spec!r} does not start with <, > or =")
    return f"'{spec[0]}'", number(spec[1:])


def expand(fields, lists):
    out = []
    for field in fields:
        if isinstance(field, str):
            if not field.startswith("@") or field[1:] not in lists:
                raise ValueError(f"unknown field list {field!r}")
            out.extend(expand(lists[field[1:]], lists))
            continue
        unknown = set(field) - FIELD_KEYS
        if unknown:
            raise ValueError(f"{field.get('name')}: unknown keys {sorted(unknown)}")
        out.append(field)
    return out


def field_row(field):
    sign, version = gate(field)
    return (
        "        {" + ", ".join([
            text(field["name"]), text(field["type"]), sign, version, text(field.get("when", "")),
            boolean(field.get("stop_if_set", False)), boolean(field.get("derived", False)),
            number(field.get("runtime_default", 0)), text(field.get("count_of", "")),
            text(field.get("component_tag", "")), boolean(field.get("component_transform", False)),
            boolean(field.get("drops", False)), text(field.get("drop_key", "")), text(field.get("drop_list", "")),
            boolean(field.get("from_actor", False)),
        ]) + "},"
    )


def generate(data):
    lists = {entry["name"]: entry["fields"] for entry in data["lists"]}
    fields, types, slots, parts = [], [], [], []
    for entry in data["types"]:
        members = expand(entry.get("members", []), lists)
        types.append("        {" + ", ".join([
            text(entry["name"]), text(entry["kind"]), text(entry.get("item", "")), text(entry.get("count_from", "")),
            str(len(fields)), str(len(members)),
        ]) + "},")
        fields.extend(members)
    slot_ids = []
    for entry in data["slots"]:
        own = expand(entry.get("fields", []), lists)
        owner = entry.get("owner", {})
        chain = {"actor": "'a'", "component": "'c'"}.get(entry.get("chain", ""), "0")
        if entry["half"] not in ("Static", "Dynamic"):
            raise ValueError(f"slot {entry['id']}: half {entry['half']!r}")
        slots.append("        {" + ", ".join([
            text(entry["row"]), boolean(entry["half"] == "Static"), "Slot::" + entry["id"], chain, str(len(fields)),
            str(len(own)), text(owner.get("property", "")), text(",".join(owner.get("classes", []))),
            text(owner.get("except", "")),
        ]) + "},")
        slot_ids.append(entry["id"])
        fields.extend(own)
    by_key = {e["row"] + "." + e["half"]: e["id"] for e in data["slots"]}
    for entry in data["classes"]:
        if entry["slot"] not in by_key:
            raise ValueError(f"{entry['class']}: unknown slot {entry['slot']!r}")
        if entry["base"] not in ("replace", "inherit"):
            raise ValueError(f"{entry['class']}: base {entry['base']!r}")
        variants = entry["variants"] if "variants" in entry else [entry["fields"]]
        for index, variant in enumerate(variants):
            own = expand(variant, lists)
            parts.append("        {" + ", ".join([
                text(entry["class"]), "Slot::" + by_key[entry["slot"]], boolean(entry["base"] == "replace"),
                str(index), str(len(fields)), str(len(own)),
            ]) + "},")
            fields.extend(own)

    complete = []
    for entry in data.get("complete", []):
        if entry["slot"] not in by_key:
            raise ValueError(f"complete: unknown slot {entry['slot']!r}")
        unknown = set(entry) - {"slot", "classes"}
        if unknown:
            raise ValueError(f"complete {entry['slot']}: unknown keys {sorted(unknown)}")
        classes = entry["classes"]
        if len(set(classes)) != len(classes) or not all(classes):
            raise ValueError(f"complete {entry['slot']}: classes repeat or are empty")
        complete.extend("        {Slot::" + by_key[entry["slot"]] + ", " + text(name) + "}," for name in classes)
    if len(complete) != len({row for row in complete}):
        raise ValueError("complete: a slot is listed twice")

    def table(kind, name, rows):
        return (f"inline Table<{kind}> {name}() {{\n    static const {kind} Rows[] = {{\n" + "\n".join(rows) +
                "\n    };\n    return {Rows, sizeof(Rows) / sizeof(Rows[0])};\n}\n")

    def counted(kind, name, rows):
        # A table that may be empty: an array of none is not C++, so it ends with an unused row.
        return (f"inline Table<{kind}> {name}() {{\n    static const {kind} Rows[] = {{\n" +
                "\n".join(rows + ["        {},"]) + f"\n    }};\n    return {{Rows, {len(rows)}}};\n}}\n")

    enum = "".join(f"    {slot},\n" for slot in slot_ids)
    return (PREAMBLE % enum + table("FieldRow", "FieldRows", [field_row(f) for f in fields]) + "\n" +
            table("TypeRow", "TypeRows", types) + "\n" + table("SlotRow", "SlotRows", slots) + "\n" +
            table("PartRow", "PartRows", parts) + "\n" + counted("CompleteRow", "CompleteRows", complete) +
            "\n} // namespace Generated\n\n} } // namespace P4MapKit::Placement\n")


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--check", action="store_true", help="fail when the header is not current")
    args = parser.parse_args(argv)
    made = generate(json.loads(SOURCE.read_text(encoding="utf-8")))
    if args.check:
        current = HEADER.read_text(encoding="utf-8") if HEADER.exists() else ""
        if current != made:
            print(f"{HEADER.relative_to(ROOT)} is not what {SOURCE.relative_to(ROOT)} gives; "
                  "run python tools/make_placement_layouts.py", file=sys.stderr)
            return 1
        return 0
    HEADER.write_text(made, encoding="utf-8", newline="\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
